/**
 * esbuild plugin that validates exported room classes match rooms.config.json.
 */

import type { Message, Plugin } from 'esbuild'
import fs from 'fs'
import path from 'path'
import type { RoomsConfigFile } from '../../mp/server/RoomConfig'
import { resolveRoomsConfigPath } from './configPath'

function error(text: string): Message {
  return { id: '', pluginName: 'rundot-server-validate', text, location: null, notes: [], detail: undefined }
}

export function esbuildValidatePlugin(projectRoot: string): Plugin {
  return {
    name: 'rundot-server-validate',
    setup(build) {
      build.onEnd((result) => {
        if (result.errors.length > 0) return // Don't validate if build already failed

        const configPath = path.resolve(projectRoot, resolveRoomsConfigPath(projectRoot))
        if (!fs.existsSync(configPath)) {
          result.errors.push(
            error('Realtime config not found. Place it at rundot/realtime.config.json. This file is required for multiplayer games.'),
          )
          return
        }

        try {
          const configContent = fs.readFileSync(configPath, 'utf-8')
          const config: RoomsConfigFile = JSON.parse(configContent)

          if (!config.rooms || !Array.isArray(config.rooms) || config.rooms.length === 0) {
            result.errors.push(
              error('rooms.config.json must contain a "rooms" array with at least one room type definition.'),
            )
            return
          }

          for (const room of config.rooms) {
            if (!room.type) {
              result.errors.push(error('Each room in rooms.config.json must have a "type" field.'))
            }
            // Deterministic (Syncplay) rooms run the platform's built-in input
            // authority and have no per-game server file. Truthiness covers the
            // declared type (`true | DeterministicRoomConfig`) and stays correct
            // for a hand-written `deterministic: false` in raw JSON.
            if (room.deterministic) {
              continue
            }
            if (!room.file) {
              result.errors.push(
                error(
                  `Room "${room.type}" in rooms.config.json must have a "file" field pointing to the GameRoom source file.`,
                ),
              )
            } else {
              const roomFilePath = path.resolve(projectRoot, room.file)
              if (!fs.existsSync(roomFilePath)) {
                result.errors.push(
                  error(`Room "${room.type}" references file "${room.file}" which does not exist.`),
                )
              }
            }
          }
        } catch (err: unknown) {
          const message = err instanceof Error ? err.message : String(err)
          result.errors.push(error(`Failed to parse rooms.config.json: ${message}`))
        }
      })
    },
  }
}
